      faq5Q: "لمن Moov'Up؟",
      faq5A:
        "من 16 إلى 30 عامًا: طلاب ثانوية مترددون بعد التخرج، طلاب جامعات يشككون في تخصصهم، شبان مهنيون يبحثون عن استقرار أو يغيّرون المسار.",
      faq6Q: "كيف يعمل مدرب الذكاء الاصطناعي Moov'Coach؟",
      faq6A:
        "متاح على مدار الساعة، يبني على الاستبيان ويجيب عن أسئلتك حول المهن والدراسة والرواتب والآفاق المهنية.",
      faq7Q: "من أين تأتي معلومات المهن والتدريب؟",
      faq7A:
        "تربط خطوات المسار بأوراق رسمية وموارد عامة للتحقق والاطلاع بعمق. يدعم Moov'Up قراراتك ولا يغني عن المصادر أو المهنيين عند الحاجة.",
      faq8Q: "هل يمكنني إعادة المسار أو استخدام الهاتف؟",
      faq8A:
        "نعم. أعد الاستبيان كلما تغيّرت خططك دون حد أقصى. التجربة مريحة على الهاتف والكمبيوتر مع أزرار وتخطيط يناسب الشاشات الصغيرة.",
