      faq2Q: "Werden meine Antworten gespeichert?",
      faq2A:
        "Offline kann der Fragebogen im Browser bleiben. Mit Konto gelten die Datenschutzregeln des Hosts.",
      faq3Q: "Ist es kostenlos?",
      faq3A: "Ja, völlig kostenlos, ohne Verpflichtung. Du kannst den Weg beliebig oft neu starten.",
      faq4Q: "Wie lange dauert der Fragebogen?",
      faq4A:
        "Etwa 3 Minuten: 10 gezielte Fragen, kein Konto nötig, sofort ein persönliches Ergebnis.",
      faq5Q: "Für wen ist Moov'Up?",
      faq5A:
        "16 bis 30 Jahre: unsichere Abiturienten, Studierende mit Zweifeln am Fach, junge Berufstätige in Wandel oder Neuorientierung.",
      faq6Q: "Wie funktioniert der KI Coach Moov'Coach?",
