applyLocaleGapPatches(TEXTS);
patchPartenairesLocales(TEXTS);

/** Incrémenté au hot-reload de ce fichier pour forcer le re-render des composants i18n. */
let textsRevision = 0;
export function getTextsRevision() {
  return textsRevision;
}

if (import.meta.hot) {
  import.meta.hot.accept(() => {
    textsRevision += 1;
    window.dispatchEvent(new Event("moovup-ui-change"));
  });
}

/** Maps storage / Intl oddities (`PT`, `pt-BR`, `português`) to `TEXTS` keys. */
const LOCALE_SYNONYMS = Object.freeze({
  arabic: "ar",
  english: "en",
  french: "fr",
  spanish: "es",
  español: "es",
  chinese: "zh",
  hindi: "hi",
  japanese: "ja",
  nihongo: "ja",
  日本語: "ja",
  portuguese: "pt",
  português: "pt",
  portugues: "pt",
  deutsch: "de",
  german: "de",
  russian: "ru",
  rus: "ru",
});

export function canonicalLanguageForTexts(language) {
  if (language === null || language === undefined) return "fr";
  const raw = String(language).trim().toLowerCase();
  if (!raw || raw === "universal") return "fr";
  if (SUPPORTED_LANGUAGES.includes(raw)) return raw;
  const primary = raw.split("-")[0];
  if (SUPPORTED_LANGUAGES.includes(primary)) return primary;
  const synonym = LOCALE_SYNONYMS[raw];
  if (synonym) return synonym;
  return raw;
}

function pickScopeText(bundle, key) {
  if (bundle && Object.prototype.hasOwnProperty.call(bundle, key)) {
    return bundle[key];
  }
  return undefined;
}

function pickQuizText(lang, key) {
  if (key === undefined) return undefined;
  const fromQuiz = pickScopeText(TEXTS[lang]?.quiz, key);
  if (fromQuiz !== undefined) return fromQuiz;
  return pickScopeText(TEXTS[lang]?.quizMeta, key);
}

export function getText(language, scope, key, fallback) {
  const lang = canonicalLanguageForTexts(language);
  let localized = pickScopeText(TEXTS[lang]?.[scope], key);
  if (localized === undefined && scope === "quiz") {
    localized = pickScopeText(TEXTS[lang]?.quizMeta, key);
  }
  if (localized !== undefined) return localized;
  if (lang === "fr") {
    const frVal = pickScopeText(TEXTS.fr?.[scope], key);
    if (frVal !== undefined) return frVal;
    if (scope === "quiz") {
      const frQuiz = pickQuizText("fr", key);
      if (frQuiz !== undefined) return frQuiz;
      const uniQuiz = pickQuizText("universal", key);
      if (uniQuiz !== undefined) return uniQuiz;
    }
    const uniVal = pickScopeText(TEXTS.universal?.[scope], key);
    if (uniVal !== undefined) return uniVal;
    return fallback;
  }
  let enVal = pickScopeText(TEXTS.en?.[scope], key);
  if (enVal === undefined && scope === "quiz") {
    enVal = pickScopeText(TEXTS.en?.quizMeta, key);
  }
  if (enVal !== undefined) return enVal;
  // `universal` is French-only fallback; never use it for en/ja/zh/… (mixed FR+EN UI).
  if (lang !== "fr" && (scope === "quiz" || scope === "quizMeta")) {
    return fallback;
  }
  return fallback;
}

function quizCopyUsesNewFormat(bundle) {
  return Boolean(bundle?.quiz?.choices?.q2?.["creer-visuels"]);
}

export function getQuizQuestionText(language, questionId) {
  const lang = canonicalLanguageForTexts(language);
  const localized = TEXTS[lang]?.quiz?.questions?.[questionId];
  if (localized && (lang === "fr" || quizCopyUsesNewFormat(TEXTS[lang]))) return localized;
  return TEXTS.fr?.quiz?.questions?.[questionId] || localized || null;
}

export function getQuizChoiceText(language, questionId, choiceValue, fallback = {}) {
  const lang = canonicalLanguageForTexts(language);
  const pick = (bundle) => bundle?.quiz?.choices?.[questionId]?.[choiceValue];
  const localized = pick(TEXTS[lang]);
  if (localized && (lang === "fr" || quizCopyUsesNewFormat(TEXTS[lang]))) return localized;
  return pick(TEXTS.fr) || pick(TEXTS.universal) || localized || fallback;
}
